    customerId: 'C-001',
    issueDate: '2025-10-10',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const draft2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  let issued1 = issueInvoice(draft1, []).value;
  const issued2 = issueInvoice(draft2, ['INV-2025-0001']).value;

  // Make first invoice partially paid
  const r1 = recordPayment(issued1, { amount: 2000, date: '2025-10-12' });
  issued1 = r1.value;

  const invoices = [issued1, issued2];

  const r = statement('C-001', invoices, '2025-10-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 2);
  const due1 = r.value.invoices[0].due;
  const due2 = r.value.invoices[1].due;
  assert.equal(r.value.totalDue, due1 + due2);
});

test('statement includes dueDate in invoice details', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(draft, []).value;
  const invoices = [issued];

  const r = statement('C-001', invoices, '2025-10-15');

  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].dueDate, '2025-10-29');
});

test('statement rejects unknown customer', () => {
  const invoices = [];
  const r = statement('C-999', invoices, '2025-12-31');

  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement shows due amounts from balanceDue', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  let issued = issueInvoice(draft, []).value;
  const r1 = recordPayment(issued, { amount: 1000, date: '2025-10-20' });
  const withPayment = r1.value;

  const invoices = [withPayment];

  const r = statement('C-001', invoices, '2025-10-15');

  assert.equal(r.ok, true);
  const inv = r.value.invoices[0];
  assert.ok(inv.due > 0);
  assert.ok(inv.total > inv.due);
});

